CREATE FUNCTION [dbo].[AKMOGUDI_KOL_ANBAR_N_FANI] (@Forms___F_MENU_ANBAR___DT2 BIGINT,@Forms___F_MENU_ANBAR___MANBAR nvarchar(10))RETURNS Table AS RETURN ( SELECT     CODE, MAND, MEGF, SMEGH, FII, MABLK, NAME, NAMES, KK, ANBAR, ANBARN, VCOD, GHEMAT, GRCOD, GRNAME, N_FANI, TOZIH, NESBAT, MANDF, LEFT(N_FANI, 2) as col1, SUBSTRING(N_FANI,3 ,2) AS col2, SUBSTRING(N_FANI,5 ,3) AS col3, SUBSTRING(N_FANI,8 ,2) AS col4, SUBSTRING(N_FANI,10 ,1) AS col5, SUBSTRING(N_FANI,11 ,2) AS col6 FROM         dbo.AKMOGUDI_KOL_ANBAR(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AKMOGUDI_KOL_ANBAR )
